//! `elm-connect check`: a tree that is current, one with a module
//! missing, one differing, a stale file beside handwritten ones, and one
//! generated by another release, in-process and through the binary for
//! the exit status.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use elm_connect::{Check, Drift};
use elm_connect_gen::{GeneratedFile, Options, SENTINEL, VERSION};

fn services_input() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../conformance/cases/services/input")
}

/// The services case's modules, `Notes/V1.elm` and
/// `Notes/V1/NotesService.elm`, as generating gives them.
fn generated() -> Vec<GeneratedFile> {
    elm_connect::generate(
        &[PathBuf::from("notes.proto")],
        &[services_input()],
        false,
        &Options::default(),
    )
    .unwrap_or_else(|report| panic!("{report:?}"))
    .files
}

/// A fresh output directory named `name` holding the generated modules.
fn written(name: &str) -> (PathBuf, Vec<GeneratedFile>) {
    let out = Path::new(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&out);
    let files = generated();
    elm_connect::write(&files, &out).expect("write the output");
    (out, files)
}

fn check_tree(files: &[GeneratedFile], out: &Path) -> Check {
    elm_connect::check(files, out).unwrap_or_else(|report| panic!("{report:?}"))
}

#[test]
fn a_tree_just_generated_is_current() {
    let (out, files) = written("check-current");
    let check = check_tree(&files, &out);
    assert!(check.is_current(), "{check:?}");
    // The package's module, its service's, and one per message and enum.
    assert_eq!(check.modules, 14);
    assert!(
        check.render().contains("14 generated modules"),
        "{}",
        check.render()
    );
}

#[test]
fn a_missing_module_is_drift() {
    let (out, files) = written("check-missing");
    fs::remove_file(out.join("Notes/V1/NotesService.elm")).expect("remove");
    let check = check_tree(&files, &out);
    assert_eq!(
        check.drift,
        [Drift::Missing {
            path: "Notes/V1/NotesService.elm".into()
        }]
    );
    assert_eq!(check.version_only(), None);
    assert!(check.render().contains("missing: "), "{}", check.render());

    let nothing = check_tree(&files, &out.join("absent"));
    assert_eq!(nothing.drift.len(), files.len());
}

#[test]
fn a_differing_module_is_drift_with_a_diff() {
    let (out, files) = written("check-differs");
    let path = out.join("Notes/V1.elm");
    let text = fs::read_to_string(&path).expect("read");
    fs::write(&path, text.replacen("-- TYPES", "-- TYPE", 1)).expect("write");
    let check = check_tree(&files, &out);
    let paths: Vec<&str> = check.drift.iter().map(Drift::path).collect();
    assert_eq!(paths, ["Notes/V1.elm"]);
    assert_eq!(check.version_only(), None);
    let report = check.render();
    assert!(report.contains("@@"), "{report}");
    let label = out.join("Notes/V1.elm");
    assert!(
        report.contains(&format!("--- {} (on disk)\n", label.display())),
        "{report}"
    );
    assert!(
        report.contains(&format!("+++ {} (generated)\n", label.display())),
        "{report}"
    );
    assert!(report.contains("\n--- TYPE\n"), "{report}");
    assert!(report.contains("+-- TYPES"), "{report}");
    assert!(report.contains("are out of date"), "{report}");
}

#[test]
fn a_stale_generated_file_is_drift_and_handwritten_ones_are_not() {
    let (out, files) = written("check-stale");
    let notes = fs::read_to_string(out.join("Notes/V1.elm")).expect("read");
    fs::create_dir_all(out.join("Old")).expect("create");
    fs::write(out.join("Old/V1.elm"), notes.replace("Notes.V1", "Old.V1")).expect("write");
    fs::write(out.join("Main.elm"), "module Main exposing (main)\n").expect("write");
    fs::write(
        out.join("Notes/Helpers.elm"),
        "-- Helpers for the generated notes client.\nmodule Notes.Helpers exposing (..)\n",
    )
    .expect("write");
    // Another invocation's module, from other protos, sharing the
    // directory.
    fs::create_dir_all(out.join("Users")).expect("create");
    fs::write(
        out.join("Users/V1.elm"),
        notes
            .replacen("from notes.proto.", "from users/v1/user.proto.", 1)
            .replace("Notes.V1", "Users.V1"),
    )
    .expect("write");
    let check = check_tree(&files, &out);
    assert_eq!(
        check.drift,
        [Drift::Stale {
            path: "Old/V1.elm".into()
        }]
    );
    assert!(check.render().contains("stale: "), "{}", check.render());
    assert_eq!(
        elm_connect::stale(&files, &out).expect("stale"),
        ["Old/V1.elm"]
    );
}

/// `content` as another release would have generated it.
fn as_release(content: &str, version: &str, sentinel: &str) -> String {
    content
        .replacen(
            &format!("elm-connect {VERSION} "),
            &format!("elm-connect {version} "),
            1,
        )
        .replacen(
            &format!("Proto.Version.{SENTINEL}\n"),
            &format!("Proto.Version.{sentinel}\n"),
            1,
        )
}

#[test]
fn a_tree_from_another_release_says_so_once() {
    let (out, files) = written("check-version");
    for file in &files {
        let path = out.join(&file.path);
        let text = fs::read_to_string(&path).expect("read");
        fs::write(&path, as_release(&text, "0.0.7", "v0_0")).expect("write");
    }
    let check = check_tree(&files, &out);
    assert_eq!(check.drift.len(), files.len());
    assert_eq!(check.version_only(), Some(vec!["0.0.7".to_owned()]));
    let report = check.render();
    assert!(
        report.contains("generated by elm-connect 0.0.7"),
        "{report}"
    );
    assert!(
        report.contains(&format!("this is elm-connect {VERSION}")),
        "{report}"
    );
    assert!(!report.contains("@@"), "{report}");

    // Only the header line changed: still one message.
    let path = out.join("Notes/V1.elm");
    fs::write(&path, as_release(&files[0].content, "0.1.99", SENTINEL)).expect("write");
    assert_eq!(
        check_tree(&files, &out).version_only(),
        Some(vec!["0.0.7".to_owned(), "0.1.99".to_owned()])
    );

    // Any other change makes it ordinary drift.
    let text = fs::read_to_string(&path).expect("read");
    fs::write(&path, text.replacen("-- TYPES", "-- TYPE", 1)).expect("write");
    let again = check_tree(&files, &out);
    assert_eq!(again.version_only(), None);
    assert!(again.render().contains("@@"));
}

/// `elm-connect check` on the services case into `out`, with `extra`
/// arguments.
fn run_check(out: &Path, extra: &[&str]) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .arg("check")
        .arg("notes.proto")
        .arg("-I")
        .arg(services_input())
        .arg("--out")
        .arg(out)
        .args(extra)
        .output()
        .expect("run elm-connect")
}

#[test]
fn the_exit_status_says_whether_the_tree_is_current() {
    let (out, _) = written("check-exit");
    let current = run_check(&out, &[]);
    assert_eq!(current.status.code(), Some(0), "{current:?}");

    let drifted = run_check(&out, &["--int64", "int"]);
    assert_eq!(drifted.status.code(), Some(1), "{drifted:?}");
    let stdout = String::from_utf8_lossy(&drifted.stdout);
    assert!(stdout.contains("are out of date"), "{stdout}");

    let failed = Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .args(["check", "missing.proto", "--out"])
        .arg(&out)
        .output()
        .expect("run elm-connect");
    assert_eq!(failed.status.code(), Some(2), "{failed:?}");
    assert!(failed.stdout.is_empty(), "{failed:?}");

    let unparsable = run_check(&out, &["--int64", "long"]);
    assert_eq!(unparsable.status.code(), Some(2), "{unparsable:?}");
}

#[test]
fn gen_warns_about_stale_files_and_deletes_nothing() {
    let (out, files) = written("gen-stale");
    let notes = fs::read_to_string(out.join("Notes/V1.elm")).expect("read");
    fs::create_dir_all(out.join("Old")).expect("create");
    fs::write(out.join("Old/V1.elm"), notes.replace("Notes.V1", "Old.V1")).expect("write");
    let output = Command::new(env!("CARGO_BIN_EXE_elm-connect"))
        .args(["gen", "notes.proto", "-I"])
        .arg(services_input())
        .arg("--out")
        .arg(&out)
        .output()
        .expect("run elm-connect");
    assert_eq!(output.status.code(), Some(0), "{output:?}");
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(stdout.lines().count(), files.len(), "{stdout}");
    let stderr = String::from_utf8_lossy(&output.stderr);
    let old = out.join("Old/V1.elm");
    assert!(
        stderr.contains(&format!(
            "warning: {} was generated by elm-connect from these protos",
            old.display()
        )),
        "{stderr}"
    );
    assert!(
        stderr.contains(&format!(
            "Wrote {} modules under {}.",
            files.len(),
            out.display()
        )),
        "{stderr}"
    );
    assert!(old.exists(), "nothing is deleted");
}
